  },

  bar(level) {
    const filled = Math.round(level / 10);
    return "█".repeat(filled) + "░".repeat(10 - filled);
  },

  dir(children) {
    return { type: "dir", children };
  },

  file(text, href = null) {
    return { type: "file", text, href };
  },

  describe(item) {
